import java.sql.*;

public class DatabaseExample {
   public static void main(String[] args) {
      try(Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydatabase", "username", "password")) {
         String query = "SELECT * FROM CUSTOMER_TABLE "
                + "JOIN ORDER_TABLE ON CUSTOMER_TABLE.customer_id = ORDER_TABLE.customer_id "
                + "JOIN COST_TABLE ON ORDER_TABLE.order_id = COST_TABLE.order_id";

         PreparedStatement preparedStatement = conn.prepareStatement(query);
         ResultSet resultSet = preparedStatement.executeQuery();

         while (resultSet.next()) {
            int orderId = resultSet.getInt("order_id");
            String customerName = resultSet.getString("customer_name");
            double cost = resultSet.getDouble("cost");

            System.out.println("Order ID: " + orderId + ", Customer Name: " + customerName + ", Cost: " + cost);
         }
      } catch(SQLException ex) {
         ex.printStackTrace();
      }
   }
}
```
